INSERT INTO `apicompany` (`name`, `description`, `long_description`, `folder`, `dateupdated`, `staffid`, `languageid`) VALUES
('Construímos soluções sólidas e econômicas.', 'Mitigamos o risco de pandemias, epidemias e enfermidades comunes que afetam a produção animal e ambientalmente o bem-estar da humanidade.', '<p>Mitigamos&#160;o&#160;risco&#160;de&#160;pandemias,&#160;epidemias&#160;e&#160;enfermidades&#160;comunes&#160;que&#160;afetam&#160;a&#160;produ&#231;&#227;o&#160;animal&#160;e&#160;ambientalmente&#160;o&#160;bem-estar&#160;da&#160;humanidade.</p><p></p><p>Somos&#160;uma&#160;deeptech&#160;global&#160;que&#160;prev&#234;&#160;doen&#231;as&#160;em&#160;plantas,&#160;animais&#160;e&#160;pessoas&#160;por&#160;meio&#160;da&#160;combina&#231;&#227;o&#160;de&#160;biotecnologia,&#160;an&#225;lise&#160;molecular&#160;e&#160;intelig&#234;ncia&#160;artificial.</p><p></p><p>Nossa&#160;abordagem&#160;&#233;&#160;a&#160;preven&#231;&#227;o:&#160;diagnosticamos&#160;sinais&#160;populacionais&#160;tempor&#225;rios&#160;para&#160;antecipar&#160;brotes,&#160;protegendo&#160;a&#160;produ&#231;&#227;o,&#160;mercados&#160;e&#160;comunidades.</p><p></p><p></p><p><strong>O&#160;que&#160;nos&#160;oferecemos</strong></p><p></p><ul><li>Plataforma&#160;digital&#160;de&#160;sa&#250;de&#160;preditiva&#160;(SaaS)&#160;&#8212;&#160;pain&#233;is,&#160;alertas&#160;e&#160;relat&#243;rios&#160;operacionais&#160;para&#160;a&#160;tomada&#160;de&#160;decis&#245;es.</li><li>Base&#160;de&#160;dados&#160;e&#160;servi&#231;os&#160;(DaaS)&#160;&#8212;&#160;reposit&#243;rio&#160;epidemiol&#243;gico&#160;personalizado&#160;com&#160;hist&#243;rico&#160;e&#160;indicadores&#160;de&#160;risco.</li><li>Mapas&#160;ambientais&#160;+&#160;an&#225;lise&#160;molecular&#160;&#8212;&#160;fluxo&#160;de&#160;laborat&#243;rio&#160;integrado&#160;que&#160;alimenta&#160;a&#160;plataforma&#160;e&#160;gera&#160;evid&#234;ncias&#160;acion&#225;veis.</li></ul>', 'company', '2025-11-11 16:51:44', 1, 1),
('We build solid and economical solutions', 'We mitigate the risk of pandemics, epidemics and common illnesses that affect animal production and potentially the well-being of humanity.', '<p>We&#160;mitigate&#160;the&#160;risk&#160;of&#160;pandemics,&#160;epidemics&#160;and&#160;common&#160;illnesses&#160;that&#160;affect&#160;animal&#160;production&#160;and&#160;potentially&#160;the&#160;well-being&#160;of&#160;humanity.</p><p></p><p>We&#160;are&#160;a&#160;global&#160;deeptech&#160;that&#160;predicts&#160;diseases&#160;in&#160;plants,&#160;animals&#160;and&#160;people&#160;through&#160;the&#160;combination&#160;of&#160;biotechnology,&#160;molecular&#160;analysis&#160;and&#160;artificial&#160;intelligence.</p><p></p><p>Our&#160;focus&#160;is&#160;on&#160;prevention:&#160;we&#160;diagnose&#160;early&#160;population&#160;signals&#160;to&#160;anticipate&#160;outbreaks,&#160;protecting&#160;production,&#160;markets&#160;and&#160;communities.</p><p></p><p></p><p><strong>What&#160;do&#160;we&#160;offer</strong></p><p></p><ul><li>Digital&#160;predictive&#160;health&#160;platform&#160;(SaaS)&#160;&#8212;&#160;dashboards,&#160;alerts&#160;and&#160;operational&#160;reports&#160;for&#160;decision&#160;making.</li><li>Database&#160;and&#160;services&#160;(DaaS)&#160;&#8212;&#160;personalized&#160;epidemiological&#160;repository&#160;with&#160;history&#160;and&#160;risk&#160;indicators.</li><li>Environmental&#160;museums&#160;+&#160;molecular&#160;analysis&#160;&#8212;&#160;integrated&#160;laboratory&#160;flow&#160;that&#160;feeds&#160;the&#160;platform&#160;and&#160;generates&#160;actionable&#160;evidence.</li></ul>', 'company', '2025-11-11 16:51:09', 1, 2),
('Construimos soluciones sólidas y económicas', 'Mitigamos el riesgo de pandemias, epidemias y enfermedades comunes que afectan la producción animal y potencialmente el bienestar de la humanidad.', '<p>Mitigamos&#160;el&#160;riesgo&#160;de&#160;pandemias,&#160;epidemias&#160;y&#160;enfermedades&#160;comunes&#160;que&#160;afectan&#160;la&#160;producci&#243;n&#160;animal&#160;y&#160;potencialmente&#160;el&#160;bienestar&#160;de&#160;la&#160;humanidad.</p><p></p><p>Somos&#160;una&#160;deeptech&#160;global&#160;que&#160;predice&#160;enfermedades&#160;en&#160;plantas,&#160;animales&#160;y&#160;personas&#160;mediante&#160;la&#160;combinaci&#243;n&#160;de&#160;biotecnolog&#237;a,&#160;an&#225;lisis&#160;molecular&#160;e&#160;inteligencia&#160;artificial.&#160;</p><p></p><p>Nuestro&#160;enfoque&#160;es&#160;la&#160;prevenci&#243;n:&#160;diagnosticamos&#160;se&#241;ales&#160;poblacionales&#160;tempranas&#160;para&#160;anticipar&#160;brotes,&#160;protegiendo&#160;producci&#243;n,&#160;mercados&#160;y&#160;comunidades.</p><p></p><p><strong>Qu&#233;&#160;ofrecemos</strong></p><p></p><ul><li>Plataforma&#160;digital&#160;de&#160;salud&#160;predictiva&#160;(SaaS)&#160;&#8212;&#160;paneles,&#160;alertas&#160;y&#160;reportes&#160;operativos&#160;para&#160;la&#160;toma&#160;de&#160;decisiones.</li><li>Base&#160;de&#160;datos&#160;y&#160;servicios&#160;(DaaS)&#160;&#8212;&#160;repositorio&#160;epidemiol&#243;gico&#160;personalizado&#160;con&#160;historial&#160;e&#160;indicadores&#160;de&#160;riesgo.</li><li>Muestreos&#160;ambientales&#160;+&#160;an&#225;lisis&#160;molecular&#160;&#8212;&#160;flujo&#160;de&#160;laboratorio&#160;integrado&#160;que&#160;alimenta&#160;la&#160;plataforma&#160;y&#160;genera&#160;evidencia&#160;accionable.</li></ul>', 'company', '2025-11-11 16:52:17', 1, 3);
