INSERT INTO `apicompany_items_translation` (`id`, `name`, `description`, `itemid`, `languageid`) VALUES
(1, 'Nossa Missão', '<p>A&nbsp;missão&nbsp;da&nbsp;metaBIX&nbsp;Biotech&nbsp;é&nbsp;reduzir&nbsp;o&nbsp;impacto&nbsp;de&nbsp;doenças&nbsp;e&nbsp;contaminações&nbsp;microbiológicas&nbsp;por&nbsp;meio&nbsp;do&nbsp;diagnóstico&nbsp;e&nbsp;análise&nbsp;de&nbsp;dados&nbsp;precisos,&nbsp;além&nbsp;da&nbsp;previsão&nbsp;inteligente&nbsp;de&nbsp;doenças&nbsp;causadas&nbsp;por&nbsp;vírus&nbsp;e&nbsp;bactérias&nbsp;a&nbsp;partir&nbsp;de&nbsp;amostras&nbsp;ambientais.</p>', 1, 1),
(2, 'Our Mission', '<p>Reduzir&nbsp;o&nbsp;impacto&nbsp;de&nbsp;doenças&nbsp;e&nbsp;contaminações&nbsp;microbiológicas&nbsp;por&nbsp;meio&nbsp;de&nbsp;diagnóstico&nbsp;de&nbsp;alta&nbsp;precisão,&nbsp;análise&nbsp;de&nbsp;dados&nbsp;e&nbsp;previsão&nbsp;inteligente&nbsp;a&nbsp;partir&nbsp;de&nbsp;mapas&nbsp;ambientais.</p>', 1, 2),
(3, 'Nuestra Misión', '<p>Reducir&nbsp;el&nbsp;impacto&nbsp;de&nbsp;enfermedades&nbsp;y&nbsp;contaminaciones&nbsp;microbiológicas&nbsp;mediante&nbsp;diagnóstico&nbsp;de&nbsp;alta&nbsp;precisión,&nbsp;análisis&nbsp;de&nbsp;datos&nbsp;y&nbsp;predicción&nbsp;inteligente&nbsp;a&nbsp;partir&nbsp;de&nbsp;muestras&nbsp;ambientales.</p>', 1, 3),
(4, 'Nossa Visão', '<p>Um&nbsp;mundo&nbsp;sem&nbsp;ameaças&nbsp;microbiológicas,&nbsp;impulsionado&nbsp;por&nbsp;tecnologia&nbsp;avançada,&nbsp;prevenção&nbsp;proativa&nbsp;e&nbsp;uma&nbsp;sociedade&nbsp;saudável&nbsp;e&nbsp;justa.</p>', 2, 1),
(5, 'Our Vision', '<p>Um&nbsp;mundo&nbsp;sem&nbsp;ameaças&nbsp;microbiológicas&nbsp;sistêmicas,&nbsp;impulsionado&nbsp;pela&nbsp;prevenção&nbsp;proativa,&nbsp;tecnologia&nbsp;avançada&nbsp;e&nbsp;equidade&nbsp;na&nbsp;saúde.</p>', 2, 2),
(6, 'Nuestra Visión', '<p>Un&nbsp;mundo&nbsp;sin&nbsp;amenazas&nbsp;microbiológicas&nbsp;sistémicas,&nbsp;impulsado&nbsp;por&nbsp;prevención&nbsp;proactiva,&nbsp;tecnología&nbsp;avanzada&nbsp;y&nbsp;equidad&nbsp;en&nbsp;salud.</p>', 2, 3),
(7, 'Valores', '<p>Velocidade,&nbsp;precisão,&nbsp;foco&nbsp;no&nbsp;cliente,&nbsp;inovação,&nbsp;confiança,&nbsp;comprometimento&nbsp;e&nbsp;facilidade&nbsp;de&nbsp;uso.</p>', 3, 1),
(8, 'Values', '<p>Velocidade,&nbsp;precisão,&nbsp;foco&nbsp;no&nbsp;cliente,&nbsp;inovação,&nbsp;confiança,&nbsp;compromisso&nbsp;e&nbsp;facilidade&nbsp;de&nbsp;uso.</p>', 3, 2),
(9, 'Valores', '<p>Velocidad,&nbsp;precisión,&nbsp;enfoque&nbsp;en&nbsp;el&nbsp;cliente,&nbsp;innovación,&nbsp;confianza,&nbsp;compromiso&nbsp;y&nbsp;facilidad&nbsp;de&nbsp;uso.</p>', 3, 3);
