INSERT INTO `apiservices` (`id`, `name`, `description`, `folder`, `file_name`, `dateadded`, `staffid`, `order`) VALUES
(1, 'Concreto armado', NULL, 'services', NULL, '2025-01-21 15:24:24', 1, 0),
(2, 'Concreto protendido', NULL, 'services', NULL, '2025-01-21 15:24:42', 1, 1),
(4, 'Estruturas metálicas', '<p>Além disso, somos especialistas em estruturas metálicas, fornecendo projetos que combinam leveza, resistência e rapidez na execução. Nossa equipe está equipada para lidar com projetos complexos e desafiadores, sempre buscando a máxima eficiência e sustentabilidade.</p>', 'services', NULL, '2025-01-21 15:25:13', 1, 2),
(5, 'Pré fabricados', '<p>Oferecemos soluções em concreto protendido, que permitem a criação de estruturas esbeltas e com maiores vãos livres, otimizando o uso do espaço e proporcionando maior flexibilidade arquitetônica.</p>', 'services', NULL, '2025-01-21 15:25:38', 1, 3),
(6, 'Alvenaria estrutural', '<p>Nossa expertise em concreto armado garante estruturas resistentes e duradouras, adequadas para uma vasta gama de aplicações, desde edifícios residenciais até grandes obras de infraestrutura. Utilizamos as melhores práticas e materiais de alta qualidade para assegurar a segurança e a longevidade de nossas construções.</p>', 'services', NULL, '2025-01-21 15:26:02', 1, 4),
(7, 'Paredes em concreto', '<p>Oferecemos soluções em concreto protendido, que permitem a criação de estruturas esbeltas e com maiores vãos livres, otimizando o uso do espaço e proporcionando maior flexibilidade arquitetônica. Nossos engenheiros altamente qualificados garantem a precisão e a eficiência em cada etapa do processo, desde o projeto até a execução.</p>', 'services', NULL, '2025-01-21 15:26:23', 1, 5);
INSERT INTO `apiservices_translation` (`id`, `name`, `description`, `serviceid`, `languageid`) VALUES
