(14, 'Pré fabricados', '<p>Oferecemos soluções em concreto protendido, que permitem a criação de estruturas esbeltas e com maiores vãos livres, otimizando o uso do espaço e proporcionando maior flexibilidade arquitetônica.</p>', 5, 2),
(15, 'Pré fabricados', '<p>Oferecemos soluções em concreto protendido, que permitem a criação de estruturas esbeltas e com maiores vãos livres, otimizando o uso do espaço e proporcionando maior flexibilidade arquitetônica.</p>', 5, 3),
(16, 'Alvenaria estrutural', '<p>Nossa expertise em concreto armado garante estruturas resistentes e duradouras, adequadas para uma vasta gama de aplicações, desde edifícios residenciais até grandes obras de infraestrutura. Utilizamos as melhores práticas e materiais de alta qualidade para assegurar a segurança e a longevidade de nossas construções.</p>', 6, 1),
(17, 'Alvenaria estrutural', '<p>Nossa expertise em concreto armado garante estruturas resistentes e duradouras, adequadas para uma vasta gama de aplicações, desde edifícios residenciais até grandes obras de infraestrutura. Utilizamos as melhores práticas e materiais de alta qualidade para assegurar a segurança e a longevidade de nossas construções.</p>', 6, 2),
(18, 'Alvenaria estrutural', '<p>Nossa expertise em concreto armado garante estruturas resistentes e duradouras, adequadas para uma vasta gama de aplicações, desde edifícios residenciais até grandes obras de infraestrutura. Utilizamos as melhores práticas e materiais de alta qualidade para assegurar a segurança e a longevidade de nossas construções.</p>', 6, 3),
(19, 'Paredes em concreto', '<p>Oferecemos soluções em concreto protendido, que permitem a criação de estruturas esbeltas e com maiores vãos livres, otimizando o uso do espaço e proporcionando maior flexibilidade arquitetônica. Nossos engenheiros altamente qualificados garantem a precisão e a eficiência em cada etapa do processo, desde o projeto até a execução.</p>', 7, 1),
(20, 'Paredes em concreto', '<p>Oferecemos soluções em concreto protendido, que permitem a criação de estruturas esbeltas e com maiores vãos livres, otimizando o uso do espaço e proporcionando maior flexibilidade arquitetônica. Nossos engenheiros altamente qualificados garantem a precisão e a eficiência em cada etapa do processo, desde o projeto até a execução.</p>', 7, 2),
(21, 'Paredes em concreto', '<p>Oferecemos soluções em concreto protendido, que permitem a criação de estruturas esbeltas e com maiores vãos livres, otimizando o uso do espaço e proporcionando maior flexibilidade arquitetônica. Nossos engenheiros altamente qualificados garantem a precisão e a eficiência em cada etapa do processo, desde o projeto até a execução.</p>', 7, 3);
