INSERT INTO `apitechnology` (`name`, `description`, `long_description`, `folder`, `dateupdated`, `staffid`, `languageid`) VALUES
('Construímos soluções sólidas e econômicas.', 'Plataforma de biovigilância baseada em dados ambientais para prevenir surtos na indústria de produção animal', '<p>Plataforma&#160;de&#160;biovigil&#226;ncia&#160;baseada&#160;em&#160;dados&#160;ambientais&#160;para&#160;prevenir&#160;surtos&#160;na&#160;ind&#250;stria&#160;de&#160;produ&#231;&#227;o&#160;animal.&#160;Antecipe&#160;amea&#231;as&#160;e&#160;proteja&#160;sua&#160;opera&#231;&#227;o&#160;com&#160;nossa&#160;tecnologia&#160;pioneira.&#160;Combinamos&#160;testes&#160;ambientais,&#160;an&#225;lises&#160;moleculares&#160;e&#160;uma&#160;plataforma&#160;digital&#160;para&#160;oferecer&#160;detec&#231;&#227;o&#160;precoce&#160;de&#160;pat&#243;genos&#160;antes&#160;que&#160;eles&#160;impactem&#160;seus&#160;resultados.&#160;Produtividade&#160;segura&#160;e&#160;reputa&#231;&#227;o&#160;preservada.</p>', 'technology', '2025-11-11 16:54:19', 1, 1),
('We build solid and economical solutions', 'Environmental data-based bio-surveillance platform to prevent outbreaks in the animal production industry.', '<p>Environmental&#160;data-based&#160;bio-surveillance&#160;platform&#160;to&#160;prevent&#160;outbreaks&#160;in&#160;the&#160;animal&#160;production&#160;industry.&#160;Anticipate&#160;threats&#160;and&#160;protect&#160;your&#160;operation&#160;with&#160;our&#160;pioneering&#160;technology.&#160;We&#160;combine&#160;environmental&#160;testing,&#160;molecular&#160;analysis,&#160;and&#160;a&#160;digital&#160;platform&#160;to&#160;offer&#160;early&#160;detection&#160;of&#160;pathogens&#160;before&#160;they&#160;impact&#160;your&#160;bottom&#160;line.&#160;Safe&#160;productivity&#160;and&#160;preserved&#160;reputation.</p>', 'technology', '2025-11-11 16:53:54', 1, 2),
('Construimos soluciones sólidas y económicas.', 'Plataforma de bio-vigilancia basada en datos ambientales para prevenir brotes en la industria de producción animal.', '<p>Plataforma&#160;de&#160;bio-vigilancia&#160;basada&#160;en&#160;datos&#160;ambientales&#160;para&#160;prevenir&#160;brotes&#160;en&#160;la&#160;industria&#160;de&#160;producci&#243;n&#160;animal.&#160;Antic&#237;pate&#160;a&#160;las&#160;amenazas&#160;y&#160;protege&#160;tu&#160;operaci&#243;n&#160;con&#160;nuestra&#160;tecnolog&#237;a&#160;pionera.&#160;Combinamos&#160;pruebas&#160;ambientales,&#160;an&#225;lisis&#160;molecular&#160;y&#160;una&#160;plataforma&#160;digital&#160;para&#160;ofrecer&#160;detecci&#243;n&#160;temprana&#160;de&#160;pat&#243;genos&#160;antes&#160;de&#160;que&#160;afecten&#160;tus&#160;resultados.&#160;Productividad&#160;segura&#160;y&#160;reputaci&#243;n&#160;preservada</p>', 'technology', '2025-11-11 16:53:34', 1, 3);
